    @Column(nullable = false)
    private Double percentualDesconto = 40.0;

    @Column(nullable = false)
    private Integer cortesParaDesconto = 5;

    @Column(nullable = false)
    private LocalDateTime ultimaAtualizacao = LocalDateTime.now();

    @Column(length = 200)
    private String atualizadoPor;

